import{_ as e,o as a,c as n,a2 as s}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Terminal UI (TUI)","description":"","frontmatter":{},"headers":[],"relativePath":"bandwidth-manager/user-guide/tui.md","filePath":"bandwidth-manager/user-guide/tui.md","lastUpdated":1782761461000}'),i={name:"bandwidth-manager/user-guide/tui.md"};function r(o,t,l,d,h,p){return a(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="terminal-ui-tui" tabindex="-1">Terminal UI (TUI) <a class="header-anchor" href="#terminal-ui-tui" aria-label="Permalink to &quot;Terminal UI (TUI)&quot;">​</a></h1><p>Bandwidth Manager ships with a fully interactive terminal interface for real-time monitoring. No browser, no Grafana — just open a terminal and run <code>bandwidth top</code>.</p><nav class="table-of-contents"><ul><li><a href="#launching">Launching</a></li><li><a href="#keyboard-shortcuts">Keyboard Shortcuts</a><ul><li><a href="#navigation">Navigation</a></li><li><a href="#panel-focus">Panel Focus</a></li><li><a href="#filtering-sorting">Filtering &amp; Sorting</a></li><li><a href="#time-window">Time Window</a></li><li><a href="#global">Global</a></li></ul></li><li><a href="#layout">Layout</a><ul><li><a href="#_1-header">1. Header</a></li><li><a href="#_2-speed-bar">2. Speed Bar</a></li><li><a href="#_3-left-panel-—-interface-list-35">3. Left Panel — Interface List (35%)</a></li><li><a href="#_4-right-panel-—-graph-stats-65">4. Right Panel — Graph + Stats (65%)</a></li><li><a href="#_5-bottom-bar">5. Bottom Bar</a></li></ul></li><li><a href="#graph-details">Graph Details</a><ul><li><a href="#color-legend">Color Legend</a></li><li><a href="#reading-the-graph">Reading the Graph</a></li><li><a href="#graph-controls">Graph Controls</a></li></ul></li><li><a href="#stats-panel">Stats Panel</a><ul><li><a href="#average-avg">Average (Avg)</a></li><li><a href="#_95th-percentile-95-ile">95th Percentile (95%ile)</a></li><li><a href="#peak">Peak</a></li><li><a href="#total-transferred">Total Transferred</a></li></ul></li><li><a href="#color-coding">Color Coding</a></li><li><a href="#mouse-support">Mouse Support</a></li><li><a href="#terminal-requirements">Terminal Requirements</a><ul><li><a href="#recommended-terminals">Recommended Terminals</a></li><li><a href="#partial-support">Partial Support</a></li><li><a href="#fonts">Fonts</a></li><li><a href="#fallback-mode">Fallback Mode</a></li></ul></li><li><a href="#troubleshooting-the-tui">Troubleshooting the TUI</a></li></ul></nav><h2 id="launching" tabindex="-1">Launching <a class="header-anchor" href="#launching" aria-label="Permalink to &quot;Launching&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bandwidth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> top</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--interval </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">second</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--interval</code></td><td><code>2</code></td><td>Poll interval in seconds (minimum <code>0.5</code>)</td></tr></tbody></table><p>The TUI connects to the running daemon. If the daemon isn&#39;t running, it will offer to start it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bandwidth top</span></span>
<span class="line"><span>✘ Daemon not running. Start it now? [Y/n]: y</span></span>
<span class="line"><span>✔ Daemon started — connecting…</span></span></code></pre></div><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Mnemonics</p><p>Most shortcuts mirror tools you already know: <code>j</code>/<code>k</code> from Vim, <code>g</code>/<code>G</code> from less, <code>q</code> from everything.</p></div><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><kbd>↑</kbd> <kbd>↓</kbd></td><td>Move selection up/down in the interface list</td></tr><tr><td><kbd>j</kbd> <kbd>k</kbd></td><td>Vim-style: move selection down/up</td></tr><tr><td><kbd>g</kbd></td><td>Jump to top of interface list</td></tr><tr><td><kbd>G</kbd></td><td>Jump to bottom of interface list</td></tr></tbody></table><h3 id="panel-focus" tabindex="-1">Panel Focus <a class="header-anchor" href="#panel-focus" aria-label="Permalink to &quot;Panel Focus&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><kbd>←</kbd> <kbd>h</kbd></td><td>Focus left panel (interfaces)</td></tr><tr><td><kbd>→</kbd> <kbd>l</kbd></td><td>Focus right panel (graph)</td></tr></tbody></table><h3 id="filtering-sorting" tabindex="-1">Filtering &amp; Sorting <a class="header-anchor" href="#filtering-sorting" aria-label="Permalink to &quot;Filtering &amp; Sorting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><kbd>Tab</kbd></td><td>Open the filter/search bar</td></tr><tr><td><kbd>s</kbd></td><td>Cycle sort order: <code>name</code> → <code>rx</code> → <code>tx</code> → <code>limit %</code></td></tr></tbody></table><p>Filter syntax inside the search bar:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eth          → filter by interface name containing &quot;eth&quot;</span></span>
<span class="line"><span>&gt;50mbps      → show only interfaces exceeding 50 Mbps</span></span>
<span class="line"><span>!docker      → exclude entries containing &quot;docker&quot;</span></span></code></pre></div><p>Press <kbd>Esc</kbd> to clear the filter.</p><h3 id="time-window" tabindex="-1">Time Window <a class="header-anchor" href="#time-window" aria-label="Permalink to &quot;Time Window&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Period</th></tr></thead><tbody><tr><td><kbd>1</kbd></td><td>1 minute</td></tr><tr><td><kbd>5</kbd></td><td>5 minutes</td></tr><tr><td><kbd>t</kbd></td><td>15 minutes</td></tr><tr><td><kbd>d</kbd></td><td>1 day</td></tr></tbody></table><p>The graph and stats panel update to reflect the selected window. A longer window smooths spikes; a shorter one reveals bursts.</p><h3 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><kbd>q</kbd></td><td>Quit (or <kbd>Ctrl</kbd>+<kbd>C</kbd>)</td></tr><tr><td><kbd>?</kbd></td><td>Show the help overlay</td></tr></tbody></table><hr><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The TUI is divided into four sections:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌── 1. Header ──────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Bandwidth Manager · live · 2s interval · 2026-06-30 09:18 UTC   │</span></span>
<span class="line"><span>├── 2. Speed Bar ───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  ██████████████████████████████████████░░░░░░░░░░░░░░  312 Mbps  │</span></span>
<span class="line"><span>├──────────────────────────────┬────────────────────────────────────┤</span></span>
<span class="line"><span>│  3. Left Panel (35%)         │  4. Right Panel (65%)              │</span></span>
<span class="line"><span>│  ┌─ Interfaces ────────────┐ │  ┌─ web-app ────────────────────┐ │</span></span>
<span class="line"><span>│  │ ● eth0     142 Mbps     │ │  │ ╭── RX ───╮                 │ │</span></span>
<span class="line"><span>│  │ ● docker0   98 Mbps     │ │  │ │███████░░│ 8.2 Mbps        │ │</span></span>
<span class="line"><span>│  │ ● wg0       52 Mbps     │ │  │ ╰─────────╯                 │ │</span></span>
<span class="line"><span>│  │   …                     │ │  │ ╭── TX ───╮                 │ │</span></span>
<span class="line"><span>│  └─────────────────────────┘ │  │ │███░░░░░░│ 2.1 Mbps        │ │</span></span>
<span class="line"><span>│                              │  │ ╰─────────╯                 │ │</span></span>
<span class="line"><span>│                              │  │ Avg:      31.4 Mbps          │ │</span></span>
<span class="line"><span>│                              │  │ 95%ile:   45.2 Mbps          │ │</span></span>
<span class="line"><span>│                              │  │ Peak:     49.8 Mbps          │ │</span></span>
<span class="line"><span>│                              │  │ Total:    142.3 GB            │ │</span></span>
<span class="line"><span>│                              │  └──────────────────────────────┘ │</span></span>
<span class="line"><span>├──────────────────────────────┴────────────────────────────────────┤</span></span>
<span class="line"><span>│  5. Bottom Bar                                                     │</span></span>
<span class="line"><span>│  q:Quit  s:Sort  tab:Filter  1/5/t/d:Period  ↑↓:Nav  ←→:Panels   │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="_1-header" tabindex="-1">1. Header <a class="header-anchor" href="#_1-header" aria-label="Permalink to &quot;1. Header&quot;">​</a></h3><p>Shows the application name, current mode (<code>live</code> or <code>paused</code>), poll interval, and local time. If the daemon connection drops, the mode changes to <code>reconnecting…</code> in yellow.</p><h3 id="_2-speed-bar" tabindex="-1">2. Speed Bar <a class="header-anchor" href="#_2-speed-bar" aria-label="Permalink to &quot;2. Speed Bar&quot;">​</a></h3><p>A horizontal bar representing total bandwidth across all interfaces. The bar fills proportionally to the highest limit configured. Colors follow the <a href="#color-coding">speed-based scheme</a> so you can spot saturation at a glance.</p><h3 id="_3-left-panel-—-interface-list-35" tabindex="-1">3. Left Panel — Interface List (35%) <a class="header-anchor" href="#_3-left-panel-—-interface-list-35" aria-label="Permalink to &quot;3. Left Panel — Interface List (35%)&quot;">​</a></h3><p>Lists every managed interface with its current total throughput. The selected interface is highlighted with a <code>●</code> marker. Each entry shows:</p><ul><li>Interface name</li><li>Current combined RX+TX throughput</li><li>Status indicator: green dot (under limit), yellow (approaching), red (at limit)</li></ul><p>The list scrolls when there are more interfaces than fit on screen.</p><h3 id="_4-right-panel-—-graph-stats-65" tabindex="-1">4. Right Panel — Graph + Stats (65%) <a class="header-anchor" href="#_4-right-panel-—-graph-stats-65" aria-label="Permalink to &quot;4. Right Panel — Graph + Stats (65%)&quot;">​</a></h3><p>Displays detailed information for the selected interface, split into two sub-panels:</p><p><strong>Graph (top half):</strong> A real-time ASCII/braille chart of inbound and outbound traffic over the selected time window.</p><p><strong>Stats (bottom half):</strong> Numerical summaries computed from the visible data.</p><h3 id="_5-bottom-bar" tabindex="-1">5. Bottom Bar <a class="header-anchor" href="#_5-bottom-bar" aria-label="Permalink to &quot;5. Bottom Bar&quot;">​</a></h3><p>A condensed reminder of all active shortcuts. The currently focused panel&#39;s shortcuts are brighter; inactive ones dim.</p><hr><h2 id="graph-details" tabindex="-1">Graph Details <a class="header-anchor" href="#graph-details" aria-label="Permalink to &quot;Graph Details&quot;">​</a></h2><p>The graph uses <strong>braille characters</strong> (Unicode <code>U+2800</code>–<code>U+28FF</code>) to render high-density time-series data. Each braille cell encodes 2×4 dots, providing <strong>8 data points per character</strong> — far denser than block-character charts.</p><h3 id="color-legend" tabindex="-1">Color Legend <a class="header-anchor" href="#color-legend" aria-label="Permalink to &quot;Color Legend&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Color</th><th>Meaning</th><th>Visual</th></tr></thead><tbody><tr><td>Green</td><td>RX (inbound)</td><td><code>⣿⣿⣿⣿⣿⣿⣿⣀⣀</code></td></tr><tr><td>Red</td><td>TX (outbound)</td><td><code>⣿⣿⣿⣀⣀⣀⣀⣀⣀</code></td></tr><tr><td>Orange</td><td>Overlap (RX+TX)</td><td><code>⣿⣿⣿⣿⣿⣿⣿⣿⣿</code></td></tr></tbody></table><p>When RX and TX values overlap at the same time point, the merged cell renders in <strong>orange</strong> to indicate both directions are active. This is common on symmetric connections or during request-response cycles.</p><h3 id="reading-the-graph" tabindex="-1">Reading the Graph <a class="header-anchor" href="#reading-the-graph" aria-label="Permalink to &quot;Reading the Graph&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ╭── RX ───╮</span></span>
<span class="line"><span> │⣿⣿⣿⣿⣿⣀⣀⣀⣀⣀│ 12.3 Mbps</span></span>
<span class="line"><span> ╰─────────╯</span></span>
<span class="line"><span> ╭── TX ───╮</span></span>
<span class="line"><span> │⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿│ 24.1 Mbps  ← notice: more filled cells</span></span>
<span class="line"><span> ╰─────────╯</span></span></code></pre></div><ul><li><strong>Left edge</strong> = oldest data point in the time window</li><li><strong>Right edge</strong> = most recent sample</li><li><strong>Dense fill</strong> (<code>⣿</code>) = higher throughput at that moment</li><li><strong>Sparse fill</strong> (<code>⣀</code>) = lower throughput</li><li><strong>Empty</strong> (<code>⠀</code>) = zero or near-zero</li></ul><h3 id="graph-controls" tabindex="-1">Graph Controls <a class="header-anchor" href="#graph-controls" aria-label="Permalink to &quot;Graph Controls&quot;">​</a></h3><p>While the right panel is focused (<kbd>→</kbd> or <kbd>l</kbd>):</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><kbd>←</kbd> <kbd>→</kbd></td><td>Scroll graph history (if paused)</td></tr><tr><td><kbd>Space</kbd></td><td>Pause/resume live updates</td></tr></tbody></table><p>When paused, a <code>⏸ PAUSED</code> indicator appears in the header, and you can scroll back through historical data up to the daemon&#39;s in-memory buffer (typically 24 hours).</p><hr><h2 id="stats-panel" tabindex="-1">Stats Panel <a class="header-anchor" href="#stats-panel" aria-label="Permalink to &quot;Stats Panel&quot;">​</a></h2><p>The stats panel shows four key metrics for the selected interface across the active time window:</p><h3 id="average-avg" tabindex="-1">Average (Avg) <a class="header-anchor" href="#average-avg" aria-label="Permalink to &quot;Average (Avg)&quot;">​</a></h3><p>The arithmetic mean of all samples in the window — smoothed but may hide short bursts.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Avg: 31.4 Mbps</span></span></code></pre></div><h3 id="_95th-percentile-95-ile" tabindex="-1">95th Percentile (95%ile) <a class="header-anchor" href="#_95th-percentile-95-ile" aria-label="Permalink to &quot;95th Percentile (95%ile)&quot;">​</a></h3><p>95% of all samples fall below this value. This is the <strong>most useful metric for capacity planning</strong> — it filters out rare spikes while capturing sustained load.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>95%ile: 45.2 Mbps</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Why 95th percentile?</p><p>ISPs and cloud providers often bill on 95th percentile. If your container bursts to 500 Mbps for 2 minutes but sits at 50 Mbps the rest of the hour, the 95th percentile will read ~52 Mbps — far more representative than the average.</p></div><h3 id="peak" tabindex="-1">Peak <a class="header-anchor" href="#peak" aria-label="Permalink to &quot;Peak&quot;">​</a></h3><p>The single highest sample in the window. Useful for identifying burst events but not for setting limits (you&#39;d over-provision).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Peak: 49.8 Mbps</span></span></code></pre></div><h3 id="total-transferred" tabindex="-1">Total Transferred <a class="header-anchor" href="#total-transferred" aria-label="Permalink to &quot;Total Transferred&quot;">​</a></h3><p>Cumulative bytes transferred (RX + TX) over the window. Displayed in human-readable units (KB → MB → GB → TB).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Total: 142.3 GB</span></span></code></pre></div><hr><h2 id="color-coding" tabindex="-1">Color Coding <a class="header-anchor" href="#color-coding" aria-label="Permalink to &quot;Color Coding&quot;">​</a></h2><p>Interface list entries and graph segments are color-coded by current throughput. The thresholds are configurable via <code>bandwidth configure set tui.thresholds.&lt;level&gt; &lt;mbps&gt;</code>.</p><table tabindex="0"><thead><tr><th>Color</th><th>Range</th><th>Meaning</th></tr></thead><tbody><tr><td>Green</td><td>&lt; 10 Mbps</td><td>Light traffic, well within limits</td></tr><tr><td>Yellow</td><td>10–100 Mbps</td><td>Moderate traffic, normal operation</td></tr><tr><td>Orange</td><td>100–500 Mbps</td><td>Heavy traffic, approaching capacity</td></tr><tr><td>Red</td><td>&gt; 500 Mbps</td><td>Saturated, likely dropping packets</td></tr></tbody></table><p>These colors apply to:</p><ul><li>Interface list entries in the left panel</li><li>Individual bars/cells in the graph</li><li>The aggregate speed bar (uses the highest interface&#39;s color)</li></ul><div class="warning custom-block"><p class="custom-block-title">Color-blind accessibility</p><p>If the default palette is hard to distinguish, set <code>tui.color_scheme: deuteranopia</code> or <code>tui.color_scheme: monochrome</code> in your config. The monochrome scheme uses character density instead of hue.</p></div><hr><h2 id="mouse-support" tabindex="-1">Mouse Support <a class="header-anchor" href="#mouse-support" aria-label="Permalink to &quot;Mouse Support&quot;">​</a></h2><p>The TUI has full mouse support. No configuration needed — it works if your terminal supports it (most do).</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td>Click</td><td>Select an interface in the left panel</td></tr><tr><td>Scroll</td><td>Scroll the interface list or graph history</td></tr><tr><td>Click buttons</td><td>Activate bottom-bar shortcuts</td></tr><tr><td>Drag</td><td>Not used (no action)</td></tr></tbody></table><p>Mouse events are handled through standard SGR extended mouse mode. If you prefer keyboard-only, mouse input doesn&#39;t interfere.</p><div class="info custom-block"><p class="custom-block-title">Disabling mouse</p><p>Set <code>tui.mouse: false</code> in your config if your terminal multiplexer (tmux, screen) has conflicting mouse bindings.</p></div><hr><h2 id="terminal-requirements" tabindex="-1">Terminal Requirements <a class="header-anchor" href="#terminal-requirements" aria-label="Permalink to &quot;Terminal Requirements&quot;">​</a></h2><p>The TUI uses advanced terminal features and works best in modern terminal emulators.</p><h3 id="recommended-terminals" tabindex="-1">Recommended Terminals <a class="header-anchor" href="#recommended-terminals" aria-label="Permalink to &quot;Recommended Terminals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Terminal</th><th style="text-align:center;">True Color</th><th style="text-align:center;">Braille</th><th style="text-align:center;">Mouse</th><th>Notes</th></tr></thead><tbody><tr><td>Kitty</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td>Native image support too</td></tr><tr><td>WezTerm</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td>Cross-platform</td></tr><tr><td>iTerm2 (macOS)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td>Enable &quot;Use Unicode version 9+ widths&quot;</td></tr><tr><td>Windows Terminal</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td>Works out of the box</td></tr><tr><td>Alacritty</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td>Lightweight, fast</td></tr><tr><td>foot (Wayland)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td>Minimal, Wayland-native</td></tr></tbody></table><h3 id="partial-support" tabindex="-1">Partial Support <a class="header-anchor" href="#partial-support" aria-label="Permalink to &quot;Partial Support&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Terminal</th><th>Issue</th><th>Workaround</th></tr></thead><tbody><tr><td>tmux</td><td>True color requires <code>set -g default-terminal &quot;tmux-256color&quot;</code> and <code>set -ga terminal-overrides &quot;,*:Tc&quot;</code></td><td>Add to <code>tmux.conf</code></td></tr><tr><td>GNOME Terminal</td><td>Braille may render with gaps</td><td>Switch to a braille-friendly font like Iosevka or JuliaMono</td></tr><tr><td>PuTTY</td><td>No braille support</td><td>Use <code>tui.graph_style: blocks</code> in config</td></tr><tr><td>macOS Terminal.app</td><td>No true color</td><td>Upgrade to iTerm2 or Kitty</td></tr></tbody></table><h3 id="fonts" tabindex="-1">Fonts <a class="header-anchor" href="#fonts" aria-label="Permalink to &quot;Fonts&quot;">​</a></h3><p>The braille graph requires a font with good Unicode Braille Patterns coverage (<code>U+2800</code>–<code>U+28FF</code>). Most modern monospace fonts work:</p><ul><li><strong>Iosevka</strong> (excellent braille rendering)</li><li><strong>JuliaMono</strong> (designed for scientific/terminal use)</li><li><strong>JetBrains Mono</strong> (good coverage, slight gaps on some sizes)</li><li><strong>Cascadia Code</strong> (works, but braille dots can be small)</li></ul><h3 id="fallback-mode" tabindex="-1">Fallback Mode <a class="header-anchor" href="#fallback-mode" aria-label="Permalink to &quot;Fallback Mode&quot;">​</a></h3><p>If your terminal doesn&#39;t support braille or true color, Bandwidth Manager detects this and falls back:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Fallback graph (block characters, 256 colors)</span></span>
<span class="line"><span>│ RX: ███████▌░░░░░░░░░░ 8.2 Mbps</span></span>
<span class="line"><span>│ TX: ███░░░░░░░░░░░░░░░ 2.1 Mbps</span></span></code></pre></div><p>Set <code>tui.graph_style: blocks</code> to force this mode permanently. It uses fewer data points but works everywhere.</p><hr><h2 id="troubleshooting-the-tui" tabindex="-1">Troubleshooting the TUI <a class="header-anchor" href="#troubleshooting-the-tui" aria-label="Permalink to &quot;Troubleshooting the TUI&quot;">​</a></h2><p><strong>&quot;The graph looks like random dots&quot;</strong> Your font doesn&#39;t render braille characters properly. Install Iosevka or JuliaMono, or set <code>tui.graph_style: blocks</code>.</p><p><strong>&quot;Colors are all white/gray&quot;</strong> Your terminal doesn&#39;t support true color. Set <code>tui.color_mode: 256</code> to use 256-color mode, or <code>tui.color_mode: 16</code> for basic ANSI.</p><p><strong>&quot;The TUI is flickering&quot;</strong> Reduce the poll interval: <code>bandwidth top --interval 5</code>. Some terminals struggle to repaint faster than 2 FPS.</p><p><strong>&quot;Mouse clicks do nothing&quot;</strong> Ensure your terminal has mouse reporting enabled. In tmux, add <code>set -g mouse on</code> to your config.</p><p><strong>&quot;The bottom bar is cut off&quot;</strong> Your terminal window is too small. Resize to at least 80×24 characters. Below that, the TUI switches to a minimal mode.</p>`,105)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
